public static String generateStatement(Invoice invoice, Map<String, Play> plays) {
    StringBuilder result = new StringBuilder("Statement for " + invoice.getCustomer() + "\n");

    double totalAmount = calculateTotalAmountAndAppendPerformances(invoice, plays, result);
    int volumeCredits = calculateTotalVolumeCredits(invoice, plays);

    result.append(String.format("Amount owed is %s\n",
            NumberFormat.getCurrencyInstance(Locale.US).format(totalAmount / 100)));
    result.append(String.format("You earned %d credits\n", volumeCredits));
    return result.toString();
}

private static double calculateTotalAmountAndAppendPerformances(Invoice invoice, Map<String, Play> plays, StringBuilder result) {
    double totalAmount = 0;
    for (Performance perf : invoice.getPerformances()) {
        Play play = plays.get(perf.getPlayID());
        double thisAmount = calculateAmountForPerformance(perf, play);

        result.append(String.format(" %s: %s (%d seats)\n",
                play.getName(), NumberFormat.getCurrencyInstance(Locale.US).format(thisAmount / 100),
                perf.getAudience()));
        totalAmount += thisAmount;
    }
    return totalAmount;
}

private static int calculateTotalVolumeCredits(Invoice invoice, Map<String, Play> plays) {
    int volumeCredits = 0;
    for (Performance perf : invoice.getPerformances()) {
        Play play = plays.get(perf.getPlayID());
        volumeCredits += calculateVolumeCreditsForPerformance(perf, play);
    }
    return volumeCredits;
}

private static double calculateAmountForPerformance(Performance perf, Play play) {
    double thisAmount = 0;
    switch (play.getType()) {
        case "tragedy":
            thisAmount = 40000;
            if (perf.getAudience() > 30) {
                thisAmount += 1000 * (perf.getAudience() - 30);
            }
            break;
        case "comedy":
            thisAmount = 30000;
            if (perf.getAudience() > 20) {
                thisAmount += 10000 + 500 * (perf.getAudience() - 20);
            }
            thisAmount += 300 * perf.getAudience();
            break;
        default:
            throw new IllegalArgumentException("Unknown type: " + play.getType());
    }
    return thisAmount;
}

private static int calculateVolumeCreditsForPerformance(Performance perf, Play play) {
    int volumeCredits = 0;
    switch (play.getType()) {
        case "tragedy":
            volumeCredits += Math.max(perf.getAudience() - 30, 0);
            break;
        case "comedy":
            volumeCredits += Math.max(perf.getAudience() - 30, 0);
            volumeCredits += Math.floor(perf.getAudience() / 5);
            break;
        default:
            throw new IllegalArgumentException("Unknown type: " + play.getType());
    }
    return volumeCredits;
}
